export const generateSegmentHeaderIdempotencyKeyRegExp = new RegExp('^[A-Za-z0-9_\\-]+$');

export const GenerateSegmentHeader = zod.object({
  'Idempotency-Key': zod
    .string()
    .min(generateSegmentHeaderIdempotencyKeyMin)
    .max(generateSegmentHeaderIdempotencyKeyMax)
    .regex(generateSegmentHeaderIdempotencyKeyRegExp)
    .describe(
      'Client-generated key (UUID recommended), scoped to the account and the operation, kept IDEMPOTENCY_TTL (24 h). Missing → 400 validation_failed; same key with a different body → 409 idempotency_key_reused; same key and body → the original result.',
    ),
});

export const generateSegmentBodyUseProductImageDefault = true;

export const GenerateSegmentBody = zod.object({
  useProductImage: zod
    .boolean()
    .default(generateSegmentBodyUseProductImageDefault)
    .describe("Send the campaign's ready product image as the reference"),
});

