/**
 * The prom-client registry of the api process: request duration histogram and counts by method, route template and
 * status class; database pool size, in use and wait time; pg-boss send failures; dropped telemetry events. Labels are
 * bounded (method, route template, status class, queue, known job type, provider, operation); never a user, record or
 * request ID. Not enveloped (exposition format). Token rule in the scope M convention (TD-D41). Exempt from rate limits;
 * not counted in the metrics windows; not audit-logged.
 * @summary Process metrics of the API in Prometheus text exposition format (internal, metrics token)
 */
export const InternalMetricsResponse = zod.string();

/**
 * Kept in memory by the api process (one instance; a restart resets it, `processStartedAt` shows when), so a reader
 * needs no stored state. Read by the `monitor` cron every 5 minutes (ALR-2, ALR-3, ALR-7, ALR-9) and by the release
 * observation step every minute (DEVOPS-PLAN §11.4, §14.4). Requests to API-900..903 are not counted. `p95Ms` is null
 * when the window has no request. ALR-9 fires when `telemetryDropped10m` is above 0 (TD-D42); the cumulative
 * `telemetryDroppedTotal` cannot show a rise to a reader without stored state and is not an alert input. Token rule in the scope M convention (TD-D41). Exempt from rate limits; not
 * audit-logged.
 * @summary Windowed request and pool summary of the API process over the last 10 and 15 minutes (internal, metrics token)
 */
export const internalMetricsWindowResponseDataPoolWaitAcquisitionsMin = 0;

export const internalMetricsWindowResponseDataPoolWaitWaitedMin = 0;

export const internalMetricsWindowResponseDataPoolWaitP95WaitMsMin = 0;

export const internalMetricsWindowResponseDataTelemetryDropped10mMin = 0;

export const internalMetricsWindowResponseDataTelemetryDroppedTotalMin = 0;

export const internalMetricsWindowResponseMetaDataRequestIdMax = 64;

export const InternalMetricsWindowResponse = zod.object({
  success: zod.literal(true),
  data: zod.object({
    processStartedAt: zod.iso.datetime({ offset: true }),
    windows: zod
      .tuple([
        zod.object({
          minutes: zod.literal(10),
        }),
        zod.object({
          minutes: zod.literal(15),
        }),
      ])
      .describe('Exactly two entries, 10 and 15 minutes, in that order'),
    poolWait: zod
      .object({
        minutes: zod.literal(10),
        acquisitions: zod.int().min(internalMetricsWindowResponseDataPoolWaitAcquisitionsMin),
        waited: zod.int().min(internalMetricsWindowResponseDataPoolWaitWaitedMin),
        p95WaitMs: zod
          .number()
          .min(internalMetricsWindowResponseDataPoolWaitP95WaitMsMin)
          .nullable(),
      })
      .describe('Database pool acquisitions that had to wait, over the last 10 minutes (ALR-7)'),
    telemetryDropped10m: zod
      .int()
      .min(internalMetricsWindowResponseDataTelemetryDropped10mMin)
      .describe(
        'Error-reporter and heartbeat events dropped over the last 10 minutes (same window end as `windows[0].to`).\nALR-9 input: the alert fires when this is above 0 (TD-D42).\n',
      ),
    telemetryDroppedTotal: zod
      .int()
      .min(internalMetricsWindowResponseDataTelemetryDroppedTotalMin)
      .describe(
        'Error-reporter and heartbeat events dropped since process start (same counter as API-902 `telemetry_dropped_total`); not an alert input',
      ),
  }),
  metaData: zod.object({
    requestId: zod.string().max(internalMetricsWindowResponseMetaDataRequestIdMax),
    timestamp: zod.iso.datetime({ offset: true }),
  }),
});
